from pathlib import Path

from ament_index_python.packages import get_package_share_directory
from launch import LaunchDescription
from launch.actions import IncludeLaunchDescription
from launch.launch_description_sources import PythonLaunchDescriptionSource
from launch_ros.actions import Node

from moveit_configs_utils import MoveItConfigsBuilder


def generate_launch_description():
    moveit_config = MoveItConfigsBuilder("arm").to_moveit_configs()
    pkg_share = Path(get_package_share_directory("arm_moveit_config"))

    ld = LaunchDescription()

    ld.add_action(
        IncludeLaunchDescription(
            PythonLaunchDescriptionSource(
                str(pkg_share / "launch" / "static_virtual_joint_tfs.launch.py")
            )
        )
    )

    ld.add_action(
        IncludeLaunchDescription(
            PythonLaunchDescriptionSource(str(pkg_share / "launch" / "rsp.launch.py"))
        )
    )

    ld.add_action(
        IncludeLaunchDescription(
            PythonLaunchDescriptionSource(
                str(pkg_share / "launch" / "move_group.launch.py")
            )
        )
    )

    # ros2_control node driving the mock hardware for the "arm" joints
    ld.add_action(
        Node(
            package="controller_manager",
            executable="ros2_control_node",
            parameters=[str(pkg_share / "config" / "ros2_controllers.yaml")],
            remappings=[
                ("/controller_manager/robot_description", "/robot_description"),
            ],
            output="screen",
        )
    )

    ld.add_action(
        IncludeLaunchDescription(
            PythonLaunchDescriptionSource(
                str(pkg_share / "launch" / "spawn_controllers.launch.py")
            )
        )
    )

    return ld

